  ('Fiestas de las Américas', 'Parade from Scissortail Park south on Robinson to Calle Dos Cinco, followed by a festival in Historic Capitol Hill.', 'festival', '2026-10-03', '2026-10-03', 'Parade 11 a.m.–1 p.m. · Festival 10 a.m.–7 p.m.', 'Historic Capitol Hill', '2512 S Harvey Ave', 'Oklahoma City', 35.4388, -97.5188, 'Free', true, null, array['hispanic-heritage', 'parade', 'music']::text[]),
